-- Timestamp-only updates must not delete an FTS row before its INSERT trigger runs.
DROP TRIGGER "posts_search_update";
CREATE TRIGGER "posts_search_update" AFTER UPDATE OF "title","body","category" ON "posts" BEGIN INSERT INTO "posts_search"("posts_search",rowid,"title","body","category") VALUES('delete',OLD.rowid,OLD."title",OLD."body",OLD."category"); INSERT INTO "posts_search"(rowid,"title","body","category") VALUES(NEW.rowid,NEW."title",NEW."body",NEW."category"); END;
