-- Use fixed-width UTC microseconds for lexicographic ordering without losing PostgreSQL precision.

-- Existing millisecond defaults are normalized only when necessary.

UPDATE "private_community_attachment_upload_receipts" SET "created_at"=CASE WHEN length("created_at")=24 AND substr("created_at",24,1)='Z' THEN substr("created_at",1,23)||'000Z' ELSE "created_at" END,"expires_at"=CASE WHEN length("expires_at")=24 AND substr("expires_at",24,1)='Z' THEN substr("expires_at",1,23)||'000Z' ELSE "expires_at" END,"consumed_at"=CASE WHEN length("consumed_at")=24 AND substr("consumed_at",24,1)='Z' THEN substr("consumed_at",1,23)||'000Z' ELSE "consumed_at" END WHERE (length("created_at")=24 AND substr("created_at",24,1)='Z') OR (length("expires_at")=24 AND substr("expires_at",24,1)='Z') OR (length("consumed_at")=24 AND substr("consumed_at",24,1)='Z');

